from services.contracts.external_market_context_result_v1 import ExternalMarketContextResultV1
from .identities import normalize_test_identity
from .timebase import REPLAY_EVALUATED_AT,build_source_timestamps
from .event_session import NONE,build_event_risk_context
def build_external_context(identity,scenario,*,evaluated_at=REPLAY_EVALUATED_AT,source_timestamp=None,quality_state='PRESENT_GOOD',event_profile=None,event_profiles=None,overrides=None):
 symbol,exchange=normalize_test_identity(*identity); timestamp=source_timestamp or evaluated_at; status='BLOCKED' if scenario.blocked else 'UNAVAILABLE' if scenario.unavailable else 'CONFLICTING' if scenario.conflicting else 'READY_WITH_WARNINGS' if scenario.direction=='HIGH_VOLATILITY' or scenario.warning else 'READY'; direction='UNAVAILABLE' if status in {'BLOCKED','UNAVAILABLE'} else 'CONFLICTING' if status=='CONFLICTING' else 'NEGATIVE' if 'BEARISH' in scenario.direction else 'POSITIVE' if 'BULLISH' in scenario.direction else 'FLAT'; blockers=('P512_EXTERNAL_BLOCKED',) if status=='BLOCKED' else (); warnings=('P512_EVENT_WARNING',) if status=='READY_WITH_WARNINGS' else (); contradictions=('P512_EXTERNAL_CONFLICT',) if status=='CONFLICTING' else ()
 event=build_event_risk_context((symbol,exchange),event_profile=event_profile or NONE,event_profiles=event_profiles,evaluated_at=timestamp)
 if event.context_status=='BLOCKED':status='BLOCKED';blockers=tuple(sorted(set(blockers+event.blockers)));warnings=tuple(sorted(set(warnings+event.warnings)))
 elif event.context_status=='READY_WITH_WARNINGS' and status=='READY':status='READY_WITH_WARNINGS';warnings=tuple(sorted(set(warnings+event.warnings)))
 values=dict(external_market_context_result_id=f'p512-external-{scenario.scenario_name}-{symbol}',created_at=timestamp,underlying_symbol=symbol,exchange=exchange,global_context=None,institutional_context=None,event_context=event,context_status=status,aggregate_direction=direction,aggregate_strength=0. if status in {'BLOCKED','UNAVAILABLE'} else .8 if scenario.strength=='STRONG' else .4 if scenario.strength=='WEAK' else .5,confirmation_state='UNAVAILABLE' if status in {'BLOCKED','UNAVAILABLE'} else 'CONFLICTING' if status=='CONFLICTING' else 'CONFIRMING' if direction in {'POSITIVE','NEGATIVE'} else 'PARTIAL',risk_level=event.event_risk_level if event.events else 'HIGH' if scenario.direction=='HIGH_VOLATILITY' else 'UNAVAILABLE' if status=='UNAVAILABLE' else 'NONE',entry_restriction_state='BLOCKED' if status=='BLOCKED' else 'UNAVAILABLE' if status=='UNAVAILABLE' else 'WARNING' if status=='READY_WITH_WARNINGS' else 'OPEN',analysis_allowed=status!='BLOCKED',new_entries_allowed=status not in {'BLOCKED','UNAVAILABLE'},available_component_count=0 if status in {'BLOCKED','UNAVAILABLE'} else 3,unavailable_component_count=3 if status in {'BLOCKED','UNAVAILABLE'} else 0,confirming_component_count=0 if direction not in {'POSITIVE','NEGATIVE'} else 1,conflicting_component_count=1 if status=='CONFLICTING' else 0,blockers=blockers,warnings=warnings,contradictions=contradictions,source_timestamps=build_source_timestamps(external_context=timestamp))
 if quality_state in {'PRESENT_PARTIAL','PRESENT_DEGRADED'}:values.update(context_status='READY_WITH_WARNINGS',aggregate_strength=.3 if quality_state=='PRESENT_DEGRADED' else .4,confirmation_state='PARTIAL',entry_restriction_state='WARNING',warnings=('P512_EXTERNAL_PARTIAL',))
 values.update(dict(overrides or {}));return ExternalMarketContextResultV1(**values)
